import React, { useState, useEffect } from "react";
import api from "@landinghub/api";
import LeadKanban from "../components/LeadKanban";

const Leads = () => {
  const [leads, setLeads] = useState([]);
  const [loading, setLoading] = useState(true);
  const [view, setView] = useState("list"); // list | kanban

  const fetchLeads = async () => {
    setLoading(true);
    try {
      const res = await api.get("/api/leads");
      setLeads(res.data);
    } catch (err) {
      console.error("Fetch leads error:", err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchLeads();
  }, []);

  const updateLead = async (id, field, value) => {
    try {
      await api.put(`/api/leads/${id}`, { [field]: value });
      setLeads((prev) =>
        prev.map((l) => (l._id === id ? { ...l, [field]: value } : l))
      );
    } catch (err) {
      alert("Cập nhật thất bại");
    }
  };

  const deleteLead = async (id) => {
    if (!window.confirm("Xóa lead này?")) return;
    try {
      await api.delete(`/api/leads/${id}`);
      setLeads((prev) => prev.filter((l) => l._id !== id));
    } catch (err) {
      alert("Xóa thất bại");
    }
  };

  if (loading) return <p>Đang tải...</p>;

  return (
    <div>
      <h2>Quản lý Leads</h2>
      <div style={{ marginBottom: "10px" }}>
        <button
          onClick={() => setView("list")}
          style={{ marginRight: "8px", background: view === "list" ? "#007bff" : "" }}
        >
          List View
        </button>
        <button
          onClick={() => setView("kanban")}
          style={{ background: view === "kanban" ? "#007bff" : "" }}
        >
          Kanban View
        </button>
        <button onClick={fetchLeads} style={{ marginLeft: "10px" }}>
          🔄 Refresh
        </button>
      </div>

      {view === "list" ? (
        <table border="1" cellPadding="8" style={{ width: "100%", borderCollapse: "collapse" }}>
          <thead>
            <tr>
              <th>Tên</th>
              <th>Email</th>
              <th>Điện thoại</th>
              <th>Trạng thái</th>
              <th>Ghi chú</th>
              <th>Hành động</th>
            </tr>
          </thead>
          <tbody>
            {leads.map((lead) => (
              <tr key={lead._id}>
                <td>{lead.name}</td>
                <td>{lead.email}</td>
                <td>{lead.phone}</td>
                <td>
                  <select
                    value={lead.status}
                    onChange={(e) => updateLead(lead._id, "status", e.target.value)}
                  >
                    <option value="new">Mới</option>
                    <option value="processing">Đang xử lý</option>
                    <option value="converted">Chuyển đổi</option>
                    <option value="lost">Mất</option>
                  </select>
                </td>
                <td>
                  <input
                    value={lead.notes || ""}
                    onChange={(e) => updateLead(lead._id, "notes", e.target.value)}
                  />
                </td>
                <td>
                  <button onClick={() => deleteLead(lead._id)} style={{ color: "red" }}>
                    Xóa
                  </button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      ) : (
        <LeadKanban
          leads={leads}
          onStatusChange={(id, val) => updateLead(id, "status", val)}
          onDelete={deleteLead}
        />
      )}
    </div>
  );
};

export default Leads;
